package com.brainserve.onboarding.reminders.api.controller;
import com.brainserve.onboarding.common.api.ApiResponse;import com.brainserve.onboarding.common.observability.RequestContext;import com.brainserve.onboarding.common.security.TenantPrincipal;import com.brainserve.onboarding.reminders.api.request.*;import com.brainserve.onboarding.reminders.api.response.*;import com.brainserve.onboarding.reminders.application.service.ReminderPolicyService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/reminder-policies") @PreAuthorize("hasAuthority('REMINDER_MANAGE')") public class ReminderPolicyController {private final ReminderPolicyService service;public ReminderPolicyController(ReminderPolicyService service){this.service=service;}@PostMapping ApiResponse<ReminderPolicyResponse> create(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody CreateReminderPolicyRequest r,HttpServletRequest req){return ApiResponse.success(service.create(p,r,req),RequestContext.requestId());}@GetMapping ApiResponse<List<ReminderPolicyResponse>> list(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){var r=service.list(p,page,size);return ApiResponse.success(r.items(),Map.of("page",r.page(),"size",r.size(),"totalElements",r.totalElements(),"totalPages",r.totalPages()),RequestContext.requestId());}@GetMapping("/{id}")ApiResponse<ReminderPolicyResponse> get(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id){return ApiResponse.success(service.get(p,id),RequestContext.requestId());}@PutMapping("/{id}")ApiResponse<ReminderPolicyResponse> update(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id,@Valid @RequestBody UpdateReminderPolicyRequest r,HttpServletRequest req){return ApiResponse.success(service.update(p,id,r,req),RequestContext.requestId());}@PostMapping("/{id}/archive")ApiResponse<ReminderPolicyResponse> archive(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id,@Valid @RequestBody ReminderVersionRequest r,HttpServletRequest req){return ApiResponse.success(service.archive(p,id,r.version(),req),RequestContext.requestId());}@GetMapping("/schedules")ApiResponse<List<ScheduledReminderResponse>> schedules(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){var r=service.schedules(p,page,size);return ApiResponse.success(r.items(),Map.of("page",r.page(),"size",r.size(),"totalElements",r.totalElements(),"totalPages",r.totalPages()),RequestContext.requestId());}}
